import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";

import {
  DATE_MAX,
  DATE_MIN,
  addCalendarMonths,
  addDays,
  compareDates,
  copenhagenToday,
  dateFromIsoDatetime,
  dateFromIsoformat,
  dateParts,
  datesEqual,
  isoformat,
  makeDate,
  parseHttpDate,
  type PlainDate,
} from "../src/plain-date.ts";
import { OverflowError, ValueError } from "../src/python-compat.ts";

// Generated by tests/equivalence/generate_python_compat_golden.py under Python 3.12.
const golden = JSON.parse(
  readFileSync(new URL("./equivalence/golden/python-compat.json", import.meta.url), "utf8"),
);

type Outcome = { output?: unknown; raises?: string };

// Compares one call with a golden row: same value, or both raise. Returns a
// description of the mismatch, or undefined.
function compare(row: Outcome, call: () => unknown, errorType: Function = ValueError): unknown {
  let got: unknown;
  try {
    got = call();
  } catch (error) {
    if (row.raises && error instanceof errorType) return undefined;
    return { row, threw: String(error) };
  }
  if (row.raises) return { row, got };
  return got === row.output ? undefined : { row, got };
}

function failures<R extends Outcome>(rows: R[], check: (row: R) => unknown): unknown[] {
  return rows.map(check).filter((problem) => problem !== undefined);
}

test("dateFromIsoformat matches Python 3.12 date.fromisoformat", () => {
  const rows = golden.date_fromisoformat as (Outcome & { input: string })[];
  assert.ok(rows.length > 300);
  assert.deepEqual(failures(rows, (row) => compare(row, () => dateFromIsoformat(row.input))), []);
});

test("dateFromIsoDatetime matches datetime.fromisoformat(s.replace('Z', '+00:00')).date()", () => {
  const rows = golden.datetime_fromisoformat_date as (Outcome & { input: string })[];
  assert.ok(rows.length > 300);
  assert.deepEqual(failures(rows, (row) => compare(row, () => dateFromIsoDatetime(row.input))), []);
});

test("dateFromIsoDatetime keeps the string's own date, without converting the offset", () => {
  assert.equal(dateFromIsoDatetime("2026-10-13T23:30:00-05:00"), "2026-10-13");
  assert.equal(dateFromIsoDatetime("2026-10-13T00:30:00+14:00"), "2026-10-13");
});

test("ISO parse errors never contain the input", () => {
  for (const parse of [dateFromIsoformat, dateFromIsoDatetime]) {
    assert.throws(
      () => parse("secret-value"),
      (error: unknown) => error instanceof ValueError && !error.message.includes("secret"),
    );
  }
});

test("addCalendarMonths matches people_due.add_calendar_months", () => {
  const rows = golden.add_calendar_months as (Outcome & { date: string; months: number })[];
  assert.deepEqual(
    failures(rows, (row) =>
      compare(row, () => addCalendarMonths(dateFromIsoformat(row.date), row.months)),
    ),
    [],
  );
});

test("addDays matches date + timedelta(days=n)", () => {
  const rows = golden.add_days as (Outcome & { date: string; days: number })[];
  assert.deepEqual(
    failures(rows, (row) =>
      compare(row, () => addDays(dateFromIsoformat(row.date), row.days), OverflowError),
    ),
    [],
  );
});

test("parseHttpDate matches parsedate_to_datetime as retry_delay uses it", () => {
  const now = Date.parse(golden.meta.http_date_now);
  const rows = golden.http_date as (Outcome & { input: string })[];
  assert.deepEqual(
    failures(rows, (row) => compare(row, () => (parseHttpDate(row.input) - now) / 1000)),
    [],
  );
});

test("copenhagenToday matches datetime.now(ZoneInfo('Europe/Copenhagen')).date()", () => {
  const rows = golden.copenhagen_today as { epoch_ms: number; output: string }[];
  assert.deepEqual(
    failures(rows, (row) => compare(row, () => copenhagenToday(new Date(row.epoch_ms)))),
    [],
  );
  assert.match(copenhagenToday(), /^\d{4}-\d{2}-\d{2}$/);
});

test("PlainDate compares, orders and exposes its parts like datetime.date", () => {
  const a = makeDate(2026, 10, 13);
  const b = makeDate(2026, 10, 14);
  assert.equal(compareDates(a, b), -1);
  assert.equal(compareDates(b, a), 1);
  assert.equal(compareDates(a, dateFromIsoformat("2026-10-13")), 0);
  assert.ok(datesEqual(a, dateFromIsoformat("20261013")));
  assert.ok(a < b);
  assert.ok(b < DATE_MAX);
  assert.ok(DATE_MIN < a);
  assert.equal(DATE_MAX, "9999-12-31");
  assert.equal(isoformat(makeDate(1, 2, 3)), "0001-02-03");
  assert.deepEqual(dateParts(a), { year: 2026, month: 10, day: 13 });
  assert.throws(() => makeDate(2026, 2, 29), ValueError);
  assert.throws(() => makeDate(0, 1, 1), ValueError);
  assert.throws(() => makeDate(2026, 1, 1.5), ValueError);

  const sortKeys: [number, PlainDate][] = [
    [1, DATE_MAX],
    [0, b],
    [0, a],
  ];
  sortKeys.sort((x, y) => x[0] - y[0] || compareDates(x[1], y[1]));
  assert.deepEqual(sortKeys, [[0, a], [0, b], [1, DATE_MAX]]);
});
